fs.mkdirSync(path.join(root, 'profile')); fs.mkdirSync(path.join(root, 'files'));
const User = require('./src/user'); const db = require('./src/database');
const before = { uploadedpicture: '/assets/uploads/profile/42-profileavatar-123.png', picture: '/assets/uploads/profile/42-profileavatar-123.png' };
