db.getObjectFields = async () => ({ 'cover:url': '/assets/uploads/files/groupCover-a.png', 'cover:thumb:url': '/assets/uploads/files/groupCoverThumb-a.jpg' });
db.deleteObjectFields = async () => {};
const Groups = {}; require('./src/groups/cover')(Groups);
(async () => {
  for (const type of ['avatar', 'cover']) for (const ext of ['png', 'jpeg', 'jpg', 'bmp']) for (const suffix of ['', '-123']) fs.writeFileSync(path.join(root, 'profile', "'`42-profile${type}${suffix}.${ext}`), '"'x');
  fs.writeFileSync(path.join(root, 'profile', '43-profileavatar.png'), 'x');
  assert(await User.getLocalCoverPath(42)); assert(await User.getLocalAvatarPath(42));
